47	/** Basic URL validation — checks structure, not reachability */
48	function isValidUrl(str: string): boolean {
49	  try {
50	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
51	    return url.protocol === "https:" || url.protocol === "http:";
52	  } catch {
53	    return false;
54	  }
55	}
56	
57	/** Normalize URL: prepend https:// if missing */
58	function normalizeUrl(str: string): string {
59	  const trimmed = str.trim();
60	  if (!trimmed) return trimmed;
61	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
62	  return `https://${trimmed}`;
63	}
