67	function statusToStep(status: string): number {
68	  switch (status) {
69	    case "pending": return 0;
70	    case "analyzing": return 3;
71	    case "completed": return SCAN_STEPS.length;
72	    case "failed": return -1;
73	    default: return 0;
74	  }
75	}
